 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the long 2-colored wall, and the distinct colored object.
    wall_row = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    wall_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    bg = max(set(v for row in grid for v in row if v != 2), key=lambda v: sum(row.count(v) for row in grid))
    obj = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (2, bg)]
    out = [row[:] for row in grid]
    if not obj:
        return out
    if wall_row is not None:
        minr = min(r for r, c in obj)
        dr = (wall_row + 1) - minr
        shifted = [(r + dr, c) for r, c in obj]
        for r, c in obj:
            out[r][c] = bg
        for r, c in shifted:
            if 0 <= r < h:
                out[r][c] = grid[next(rr for rr, cc in obj if cc == c and rr + dr == r)][c]
        stripe = max(r for r, c in shifted) + 1
        if stripe < h:
            out[stripe] = [8] * w
        return out
    if wall_col is not None:
        minc = min(c for r, c in obj)
        dc = (wall_col + 1) - minc
        shifted = [(r, c + dc) for r, c in obj]
        for r, c in obj:
            out[r][c] = bg
        for r, c in shifted:
            if 0 <= c < w:
                out[r][c] = next(grid[rr][cc] for rr, cc in obj if rr == r and cc + dc == c)
        stripe = max(c for r, c in shifted) + 1
        if stripe < w:
            for r in range(h):
                out[r][stripe] = 8
        return out
    return out
